package org.brightstats.desktop;
import java.util.*;import javafx.scene.chart.*;import javafx.scene.control.*;import javafx.scene.layout.VBox;import javafx.geometry.Insets;import org.brightstats.stats.*;
final class LatentLikelihoodPlots {
 private LatentLikelihoodPlots(){}
 static void add(TabPane tabs,LatentInteractionSem.Fit fit){if(fit.model().interactions().isEmpty())return;VBox panel=new VBox(12);panel.setPadding(new Insets(12));Label note=UiAppearance.label("Conditional structural slopes in original fixed-marker latent units; centered latent predictors have mean zero. Other latent values are held at zero. Bands are pointwise "+(Math.round(fit.options().confidence()*10000)/100.0)+"% observed-information Wald intervals, separate from bootstrap coefficient intervals; these curves do not establish causation.");note.setWrapText(true);panel.getChildren().add(note);double[][] covariance=fit.parameterCovariance();double critical=new org.apache.commons.math3.distribution.NormalDistribution().inverseCumulativeProbability((1+fit.options().confidence())/2);for(int term=0;term<fit.model().interactions().size();term++){var product=fit.model().interactions().get(term);int focus=product.first(),moderator=product.second();String source=fit.model().predictors().get(focus).name(),condition=fit.model().predictors().get(moderator).name();String betaLabel="Main effect: "+source,gammaLabel="Latent product: "+source+" * "+condition;int ib=-1,ig=-1;for(int j=0;j<fit.terms().size();j++){if(fit.terms().get(j).name().equals(betaLabel))ib=j;if(fit.terms().get(j).name().equals(gammaLabel))ig=j;}NumberAxis x=new NumberAxis(),y=new NumberAxis();x.setLabel(condition+" latent value (mean zero)");y.setLabel("d "+fit.model().outcome().name()+" / d "+source);LineChart<Number,Number> chart=new LineChart<>(x,y);chart.setTitle(source+" conditional on "+condition);chart.setAnimated(false);chart.setCreateSymbols(false);chart.setMinHeight(360);var center=new XYChart.Series<Number,Number>();center.setName("Conditional slope");var low=new XYChart.Series<Number,Number>();low.setName("Pointwise lower");var high=new XYChart.Series<Number,Number>();high.setName("Pointwise upper");double sd=Math.sqrt(fit.predictorCovariance()[moderator][moderator]);boolean bounds=ib>=0&&ig>=0&&Double.isFinite(covariance[ib][ib])&&Double.isFinite(covariance[ig][ig]);for(int j=0;j<41;j++){double value=-2*sd+j*.1*sd,multiplier=value*(focus==moderator?2:1),slope=fit.mainEffects()[focus]+fit.nonlinearEffects()[term]*multiplier;center.getData().add(new XYChart.Data<>(value,slope));if(bounds){double variance=covariance[ib][ib]+multiplier*multiplier*covariance[ig][ig]+2*multiplier*covariance[ib][ig];double tolerance=1e-10*(Math.abs(covariance[ib][ib])+multiplier*multiplier*Math.abs(covariance[ig][ig])+2*Math.abs(multiplier*covariance[ib][ig]));if(variance< -tolerance){bounds=false;continue;}double error=Math.sqrt(Math.max(0,variance));low.getData().add(new XYChart.Data<>(value,slope-critical*error));high.getData().add(new XYChart.Data<>(value,slope+critical*error));}}chart.getData().add(center);if(bounds){chart.getData().add(low);chart.getData().add(high);}panel.getChildren().add(chart);}ScrollPane scroll=new ScrollPane(panel);scroll.setFitToWidth(true);Tab tab=new Tab("Latent conditional slopes",scroll);tab.setClosable(false);tabs.getTabs().add(tab);}
}
